            assert_physical_equal(left['physical'], right['physical'], f'{stage} named/native result {index}')
        records['common_actual_fp32_operands_masters_and_physical_specs_exact'] = True
        records['comparisons'] = {name: [prior.difference(a, b) for a, b in zip(values[left], values[right], strict=True)] for name, left, right in [('named_vs_native', 'named', 'native')]}
        prior.write_json(self.output / f'last-{stage}.json', records)
        print('BLOCK_REPLAY ' + json.dumps({'stage': stage, 'named_vs_native': records['comparisons']['named_vs_native']}), flush=True)
        return values


